// PLAN
// 1) COMPOSITION: dark gradient backdrop plane at z=-2.5 fills the stage; a machined
//    metal-toned platform sits at y=-1.3; the hero — a triangular glass prism with an
//    emissive red octahedron core — floats centered at origin (~58% frame height);
//    a caustic gradient streak lies on the floor beneath it; headline sits 1.75u below
//    center, caption 0.5u further below, per the effects spec baseline rule.
// 2) LIGHT RIG: rig-noir-crimson — warm key spot (#f4f0ea, i58) front-right, crimson rim
//    spot (#ff2a38, i52) behind-left carrying the accent hue along both prism edges, a
//    soft crimson point kicker, plus a near-zero ambient floor so the stage never voids.
// 3) MATERIALS: MeshPhysicalNodeMaterial glass — transmission 1, ior 1.55, dispersion
//    0.18, iridescence 1.0/1.3, roughness 0.08, clearcoat 0.25 — never flat glassmorphism;
//    emissive core capped at 2.2; caustic + backdrop are TSL gradient MeshBasicNodeMaterials.
// 4) MOTION: hover -> depth-rotate primitive (max 10deg) toward cursor with weighted
//    settle release; idle breathing scale <=2% on the prism group via gsap.
// 5) FOCAL ELEMENT: the glass prism's emissive red core is the single brightest read;
//    everything else (rim light, caustic, text) is graded below it.

import {
  Group,
  Mesh,
  CylinderGeometry,
  OctahedronGeometry,
  PlaneGeometry,
  CircleGeometry,
  SpotLight,
  PointLight,
  AmbientLight,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DoubleSide,
  MathUtils,
} from 'three/webgpu';
import { uv, color, mix, smoothstep, clamp } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  background: '#0b0b10',
  surface: '#101017',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
};

function buildBackdrop() {
  // color.background / color.gradient
  const geo = new PlaneGeometry(7, 6);
  const mat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const t = uv().y;
  const stop0 = color(COLORS.background);
  const stop1 = color('#12121a');
  const stop2 = color(COLORS.ink);
  const lowMix = mix(stop0, stop1, clamp(t.div(0.6), 0.0, 1.0));
  const band = smoothstep(0.55, 0.68, t);
  mat.colorNode = mix(lowMix, mix(stop1, stop2, clamp(t.sub(0.6).div(0.4), 0.0, 1.0)), band);
  const mesh = new Mesh(geo, mat);
  mesh.position.z = -2.5;
  return { mesh, geo, mat };
}

function buildPlatform() {
  // color.surface — explicit machined-surface plinth beneath the prism
  const geo = new CircleGeometry(1.7, 48);
  const mat = new MeshStandardNodeMaterial({
    color: COLORS.surface,
    roughness: 0.55,
    metalness: 0.4,
  });
  const mesh = new Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = -1.3;
  return { mesh, geo, mat };
}

function buildContactShadow() {
  const geo = new PlaneGeometry(2.6, 2.6);
  const mat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const centered = uv().sub(0.5);
  const dist = centered.length();
  mat.colorNode = color('#000000');
  mat.opacityNode = smoothstep(0.5, 0.02, dist).mul(0.5);
  const mesh = new Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = -1.29;
  return { mesh, geo, mat };
}

function buildPrism() {
  // effects.spec — equilateral cross-section 1.2 units per side, length 1.8, axis horizontal
  const side = 1.2;
  const R = side / Math.sqrt(3);
  const length = 1.8;
  const geo = new CylinderGeometry(R, R, length, 3, 1, false);
  geo.rotateZ(Math.PI / 2); // axis -> horizontal (X)

  const mat = new MeshPhysicalNodeMaterial({
    color: COLORS.paper,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    attenuationColor: COLORS.paper,
    attenuationDistance: 2.5,
    metalness: 0.0,
    side: DoubleSide,
    transparent: true,
  });
  mat.iridescenceThicknessRange = [120, 480];
  if ('dispersion' in mat) mat.dispersion = 0.18; // TSL/physical dispersion pass, RGB split ~0.18

  const mesh = new Mesh(geo, mat);
  mesh.rotation.z = MathUtils.degToRad(12);
  mesh.rotation.y = MathUtils.degToRad(20);
  return { mesh, geo, mat };
}

function buildEmissiveCore() {
  const geo = new OctahedronGeometry(0.35, 0);
  const mat = new MeshStandardNodeMaterial({
    color: COLORS.accent,
    emissive: COLORS.accent,
    emissiveIntensity: 2.2, // capped under 2.5 AgX red-clip ceiling
    roughness: 0.4,
    metalness: 0.1,
  });
  const mesh = new Mesh(geo, mat);
  return { mesh, geo, mat };
}

function buildCausticStreak() {
  const geo = new PlaneGeometry(2.4, 0.5);
  const mat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, side: DoubleSide });
  const t = uv().x;
  const c0 = color(COLORS.accent);
  const c1 = color(COLORS.paper);
  const c2 = color('#9fb0c4');
  const seg1 = mix(c0, c1, smoothstep(0.2, 0.5, t));
  const grad = mix(seg1, c2, smoothstep(0.5, 0.8, t));
  mat.colorNode = grad;
  mat.opacityNode = smoothstep(0.0, 0.15, t).mul(smoothstep(1.0, 0.85, t)).mul(0.35);
  const mesh = new Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = -1.1;
  return { mesh, geo, mat };
}

function buildLights() {
  // LIGHT RIG preset rig-noir-crimson (subject-relative)
  const ambient = new AmbientLight('#ffffff', 0.04);

  const key = new SpotLight(0xf4f0ea, 58, 0, 0.42, 0.3, 1.0);
  key.position.set(3, 1.8, 0.8);
  key.target.position.set(0, 0.5, 0);

  const rim = new SpotLight(0xff2a38, 52, 0, 0.55, 0.5, 1.0);
  rim.position.set(-2.2, 1.4, -2);
  rim.target.position.set(0, 0.6, 0);

  const kicker = new PointLight(0xff2a38, 5, 6, 2);
  kicker.position.set(-1, 0.2, 1.6);

  return { ambient, key, rim, kicker };
}

function buildHeadline(ctx, text) {
  const node = ctx.fontAtlas.createText(text, {
    fontSize: 68,
    color: COLORS.paper,
    align: 'center',
  });
  node.position.set(0, -1.75, 0.2);
  return node;
}

function buildCaption(ctx, text) {
  const node = ctx.fontAtlas.createText(text, {
    fontSize: 18,
    color: COLORS.accent,
    align: 'center',
    letterSpacingPx: 1.6,
  });
  node.position.set(0, -2.25, 0.2);
  return node;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const disposables = [];
  const timelines = [];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItem = items.find((i) => i.role === 'caption');
  const headlineText = headlineItem?.text ?? 'Light, machined.';
  const captionText = captionItem?.text ?? 'SAPPHIRE OVER DIAL / ZERO DISTORTION';

  // --- Backdrop / stage grading (color.background, color.gradient) ---
  const backdrop = buildBackdrop();
  group.add(backdrop.mesh);
  disposables.push(backdrop.geo, backdrop.mat);

  // --- Platform (color.surface) ---
  const platform = buildPlatform();
  group.add(platform.mesh);
  disposables.push(platform.geo, platform.mat);

  // --- Contact shadow ---
  const shadow = buildContactShadow();
  group.add(shadow.mesh);
  disposables.push(shadow.geo, shadow.mat);

  // --- Caustic streak (effects.spec) ---
  const caustic = buildCausticStreak();
  group.add(caustic.mesh);
  disposables.push(caustic.geo, caustic.mat);

  // --- Prism group (subject) ---
  const prismGroup = new THREE.Group();
  const prism = buildPrism();
  const core = buildEmissiveCore();
  prismGroup.add(prism.mesh);
  prismGroup.add(core.mesh);
  group.add(prismGroup);
  disposables.push(prism.geo, prism.mat, core.geo, core.mat);

  // --- Lights (rig-noir-crimson) ---
  const lights = buildLights();
  group.add(lights.ambient, lights.key, lights.key.target, lights.rim, lights.rim.target, lights.kicker);

  // --- Text (color.paper / color.accent) ---
  const headline = buildHeadline(ctx, headlineText);
  const caption = buildCaption(ctx, captionText);
  group.add(headline, caption);

  // --- Idle breathing (weighted, <=2%) ---
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(prismGroup.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(idleTl);

  // --- Entrance settle ---
  const enterTl = gsap.timeline();
  enterTl.fromTo(
    prismGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  enterTl.fromTo(group.position, { y: 0.4 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  timelines.push(enterTl);

  // --- Cinematic primitives (primitive.depth-rotate) ---
  const primitiveHandles = [];
  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const spec of primitiveSpecs) {
    const fn = ctx.primitives?.[spec.name];
    if (typeof fn !== 'function') continue;
    const result = fn(prismGroup, { ...(spec.params ?? {}), trigger: spec.trigger });
    primitiveHandles.push(result);
    if (result?.timeline?.eventCallback) {
      result.timeline.eventCallback('onUpdate', () => {
        const maxDeg = spec.params?.maxDeg ?? 10;
        const tilt = Math.min(
          1,
          Math.abs(prismGroup.rotation.y - MathUtils.degToRad(20)) / MathUtils.degToRad(Math.max(1, maxDeg))
        );
        caustic.mesh.scale.x = 1 + 0.08 * tilt;
      });
    }
  }

  group.userData.handlers = group.userData.handlers ?? {};

  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) {
      try {
        h?.cleanup?.();
      } catch (e) {
        /* no-op */
      }
    }
    for (const d of disposables) {
      d?.dispose?.();
    }
    lights.key.dispose?.();
    lights.rim.dispose?.();
    lights.kicker.dispose?.();
    headline?.userData?.cleanup?.();
    caption?.userData?.cleanup?.();
  };

  return group;
}

